// === 内层：领域模型（Entities） ===
public class Order {
    private OrderId id;
    private OrderStatus status;
    private Money totalAmount;
    private List<OrderLine> lines;

    public static Order create(List<OrderLine> lines) {
        if (lines == null || lines.isEmpty()) {
            throw new IllegalArgumentException("订单明细不能为空");
        }
        Order order = new Order();
        order.lines = new ArrayList<>(lines);
        order.totalAmount = lines.stream()
            .map(OrderLine::subtotal)
            .reduce(Money.ZERO, Money::add);
        order.status = OrderStatus.CREATED;
        return order;
    }

    public void cancel() {
        if (status == OrderStatus.PAID) {
            throw new IllegalStateException("已支付订单不能取消");
        }
        this.status = OrderStatus.CANCELLED;
    }
}

// === 内层：端口（Use Cases 需要的能力） ===
public interface OrderRepository {
    Order save(Order order);
    Optional<Order> findById(OrderId id);
}

public interface DomainEventPublisher {
    void publish(DomainEvent event);
}

// === 内层：用例（Use Cases） ===
public class PlaceOrderUseCase {
    private final OrderRepository orderRepo;
    private final InventoryPort inventoryPort;
    private final DomainEventPublisher eventPublisher;

    public PlaceOrderUseCase(OrderRepository orderRepo,
                             InventoryPort inventoryPort,
                             DomainEventPublisher eventPublisher) {
        this.orderRepo = orderRepo;
        this.inventoryPort = inventoryPort;
        this.eventPublisher = eventPublisher;
    }

    public OrderId execute(PlaceOrderCommand cmd) {
        // 校验库存
        inventoryPort.reserve(cmd.skuId(), cmd.quantity());
        // 创建订单（领域模型内部保证不变量）
        Order order = Order.create(cmd.lines());
        // 保存
        orderRepo.save(order);
        // 发布领域事件
        eventPublisher.publish(new OrderCreatedEvent(order.id(), order.totalAmount()));
        return order.id();
    }
}

// === 外层：适配器实现（Infrastructure） ===
@Repository
public class JpaOrderRepository implements OrderRepository {
    private final SpringDataOrderJpaRepo jpaRepo;
    private final OrderMapper mapper;

    @Override
    public Order save(Order order) {
        OrderEntity entity = mapper.toEntity(order);
        jpaRepo.save(entity);
        return mapper.toDomain(entity);
    }

    @Override
    public Optional<Order> findById(OrderId id) {
        return jpaRepo.findById(id.value()).map(mapper::toDomain);
    }
}

// === 外层：组合根（Configuration） ===
@Configuration
public class OrderConfig {
    @Bean
    public PlaceOrderUseCase placeOrderUseCase(
            OrderRepository orderRepo,
            InventoryPort inventoryPort,
            DomainEventPublisher eventPublisher) {
        return new PlaceOrderUseCase(orderRepo, inventoryPort, eventPublisher);
    }
}
